export type PageBlockOf<T extends PageBlockType> = Extract<PageBlock, { type: T }>;

/** Machine-readable reason, so an editor can show its own (localized) message. */
export type BlockErrorCode = 'not_list' | 'too_many' | 'bad_block' | 'bad_type' | 'bad_id' | 'duplicate_id' | 'too_long' | 'bad_url' | 'bad_ref' | 'too_many_items' | 'bad_value' | 'bad_email';

export class BlockError extends Error {
   readonly code: BlockErrorCode;
   readonly index: number | null;
   constructor(code: BlockErrorCode, index: number | null, message: string) {
      super(index === null ? message : `Block ${index + 1}: ${message}`);
      this.name = 'BlockError';
      this.code = code;
      this.index = index;
   }
}

export const BLOCK_ID = /^[a-z0-9][a-z0-9-]{0,39}$/;
/** A videos-platform id. */
export const BLOCK_REF_ID = /^[A-Za-z0-9_-]{1,128}$/;
const EMAIL = /^[^\s@<>()[\]\\,;:"]{1,64}@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;

/** "/…" on the site (not "//") or an absolute https URL. */
export function validBlockUrl(url: string): boolean {
   if (!url || url.length > 2048) return false;
   if (url.startsWith('/')) return !url.startsWith('//') && !/[\\\s]/.test(url);
   try {
      return new URL(url).protocol === 'https:';
   } catch {
      return false;
   }
}

export function validEmail(s: string): boolean {
   return s.length <= 254 && EMAIL.test(s);
}

export function newBlockId(): string {
   const c = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
   const rnd = c?.randomUUID ? c.randomUUID().replace(/-/g, '') : Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
   return `b${rnd.slice(0, 12)}`;
}

type Obj = Record<string, unknown>;
const isObj = (v: unknown): v is Obj => !!v && typeof v === 'object' && !Array.isArray(v);

function text(v: unknown, max: number, i: number, field: string): string {
   if (v === undefined || v === null) return '';
   if (typeof v !== 'string') throw new BlockError('bad_value', i, `${field} must be text`);
   const s = v.replace(/\r\n?/g, '\n');
   if (s.length > max) throw new BlockError('too_long', i, `${field} is longer than ${max} characters`);
   return s;
}
const line = (v: unknown, max: number, i: number, field: string) => text(v, max, i, field).replace(/\s*\n\s*/g, ' ').trim();

function oneOf<T extends string | number>(v: unknown, values: readonly T[], def: T, i: number, field: string): T {
   if (v === undefined || v === null || v === '') return def;
   const n = typeof def === 'number' && typeof v === 'string' && /^\d+$/.test(v) ? Number(v) : v;
   if (!values.includes(n as T)) throw new BlockError('bad_value', i, `${field} must be one of ${values.join(', ')}`);
   return n as T;
}

function mediaId(v: unknown, i: number): number | null {
   if (v === undefined || v === null || v === '') return null;
   const n = typeof v === 'string' && /^\d+$/.test(v) ? Number(v) : v;
   if (typeof n !== 'number' || !Number.isSafeInteger(n) || n < 1) throw new BlockError('bad_ref', i, 'the image must be a media library item');
   return n;
}

function imageRef(o: Obj, i: number): ImageRef {
   return { media_id: mediaId(o.media_id, i), alt: line(o.alt, SHORT_TEXT, i, 'alt text'), caption: line(o.caption, SHORT_TEXT, i, 'caption') };
}

function refId(v: unknown, i: number, optional: boolean): string {
   if ((v === undefined || v === null || v === '') && optional) return '';
   if (typeof v !== 'string' || !BLOCK_REF_ID.test(v)) throw new BlockError('bad_ref', i, 'the video must be chosen from the videos platform');
   return v;
}

function url(v: unknown, i: number): string {
   const u = line(v, 2048, i, 'link');
   if (u && !validBlockUrl(u)) throw new BlockError('bad_url', i, 'the link must be a "/…" path on the site or an https:// address');
   return u;
}

function list<T>(v: unknown, max: number, i: number, field: string, each: (x: Obj) => T): T[] {
   if (v === undefined || v === null) return [];
   if (!Array.isArray(v)) throw new BlockError('bad_value', i, `${field} must be a list`);
   if (v.length > max) throw new BlockError('too_many_items', i, `${field} can have at most ${max} items`);
   return v.map((x) => {
      if (!isObj(x)) throw new BlockError('bad_value', i, `${field} items must be objects`);
      return each(x);
   });
}

function int(v: unknown, def: number, min: number, max: number, i: number, field: string): number {
   const n = v === undefined || v === null || v === '' ? def : Number(v);
   if (!Number.isInteger(n) || n < min || n > max) throw new BlockError('bad_value', i, `${field} must be ${min} to ${max}`);
   return n;
}

/** A block's style: given options checked, the rest from the type's default (v1 blocks have none). */
function styleOf(type: PageBlockType, raw: unknown, i: number, legacyWidth?: Width): BlockStyle {
   const d = DEFAULT_STYLE[type];
   const s = isObj(raw) ? raw : {};
   const allowed = STYLE_OPTIONS[type];
   const pick = <K extends keyof BlockStyle>(k: K, values: readonly BlockStyle[K][], def: BlockStyle[K]): BlockStyle[K] => (allowed.includes(k) ? oneOf(s[k], values, def, i, `style ${k}`) : d[k]);
   return {
      align: pick('align', ALIGNS, d.align),
      width: pick('width', WIDTHS, (s.width === undefined && legacyWidth) || d.width),
      tone: pick('tone', TONES, d.tone),
      space: pick('space', SPACES, d.space),
   };
}

function normalizeOne(raw: unknown, i: number): PageBlock {
   if (!isObj(raw)) throw new BlockError('bad_block', i, 'must be an object');
   const id = raw.id;
   if (typeof id !== 'string' || !BLOCK_ID.test(id)) throw new BlockError('bad_id', i, 'has no valid id');
   const type = raw.type as PageBlockType;
   if (!PAGE_BLOCK_TYPES.includes(type)) throw new BlockError('bad_type', i, 'is not a known block type');
   switch (type) {
      case 'hero': {
         const background = oneOf(raw.background, ['gradient', 'image', 'plain'] as const, 'gradient', i, 'background');
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            eyebrow: line(raw.eyebrow, LABEL_TEXT, i, 'eyebrow'),
            title: line(raw.title, SHORT_TEXT, i, 'title'),
            subtitle: text(raw.subtitle, CTA_TEXT, i, 'subtitle').trim(),
            background,
            media_id: mediaId(raw.media_id, i),
            alt: line(raw.alt, SHORT_TEXT, i, 'alt text'),
            height: oneOf(raw.height, ['s', 'm', 'l'] as const, 'm', i, 'height'),
            buttons: list(raw.buttons, MAX_HERO_BUTTONS, i, 'buttons', (x) => ({
               label: line(x.label, LABEL_TEXT, i, 'button label'),
               url: url(x.url, i),
               variant: oneOf(x.variant, ['primary', 'secondary'] as const, 'primary', i, 'button style'),
            })),
         };
      }
      case 'markdown':
         return { id, type, appearance: styleOf(type, raw.appearance, i), text: text(raw.text, LONG_TEXT, i, 'text') };
      case 'image': {
         const size = oneOf(raw.size, ['content', 'wide'] as const, 'content', i, 'size');
         const appearance = styleOf(type, raw.appearance, i, size === 'wide' ? 'wide' : undefined);
         return { id, type, appearance, ...imageRef(raw, i), size: appearance.width === 'content' ? 'content' : 'wide' };
      }
      case 'gallery':
         return { id, type, appearance: styleOf(type, raw.appearance, i), columns: oneOf(raw.columns, [2, 3, 4] as const, 3, i, 'columns'), items: list(raw.items, MAX_GALLERY, i, 'images', (x) => imageRef(x, i)) };
      case 'layout':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            columns: oneOf(raw.columns, [2, 3] as const, 2, i, 'columns'),
            items: list(raw.items, 3, i, 'columns', (x) => ({
               media_id: mediaId(x.media_id, i),
               alt: line(x.alt, SHORT_TEXT, i, 'alt text'),
               heading: line(x.heading, SHORT_TEXT, i, 'heading'),
               text: text(x.text, COLUMN_TEXT, i, 'text'),
               label: line(x.label, LABEL_TEXT, i, 'link label'),
               url: url(x.url, i),
            })),
         };
      case 'columns':
         return { id, type, appearance: styleOf(type, raw.appearance, i), text: text(raw.text, LONG_TEXT, i, 'text'), ...imageRef(raw, i), image_side: oneOf(raw.image_side, ['start', 'end'] as const, 'end', i, 'image side') };
      case 'cardgrid':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            intro: text(raw.intro, CTA_TEXT, i, 'intro').trim(),
            columns: oneOf(raw.columns, [2, 3, 4] as const, 3, i, 'columns'),
            items: list(raw.items, MAX_CARD_ITEMS, i, 'cards', (x) => ({
               media_id: mediaId(x.media_id, i),
               alt: line(x.alt, SHORT_TEXT, i, 'alt text'),
               title: line(x.title, SHORT_TEXT, i, 'card title'),
               text: text(x.text, CARD_TEXT, i, 'card text').trim(),
               label: line(x.label, LABEL_TEXT, i, 'link label'),
               url: url(x.url, i),
            })),
         };
      case 'cta':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            text: text(raw.text, CTA_TEXT, i, 'text').trim(),
            label: line(raw.label, LABEL_TEXT, i, 'button label'),
            url: url(raw.url, i),
            tone: oneOf(raw.tone, ['primary', 'quiet'] as const, 'primary', i, 'button style'),
         };
      case 'quote':
         return { id, type, appearance: styleOf(type, raw.appearance, i), variant: oneOf(raw.variant, ['quote', 'callout'] as const, 'quote', i, 'style'), text: text(raw.text, QUOTE_TEXT, i, 'text').trim(), cite: line(raw.cite, SHORT_TEXT, i, 'source') };
      case 'faq':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            items: list(raw.items, MAX_FAQ, i, 'questions', (x) => ({ q: line(x.q, SHORT_TEXT, i, 'question'), a: text(x.a, FAQ_ANSWER, i, 'answer').trim() })),
         };
      case 'video':
         return { id, type, appearance: styleOf(type, raw.appearance, i), kind: oneOf(raw.kind, ['video', 'playlist'] as const, 'video', i, 'kind'), ref_id: refId(raw.ref_id, i, true), caption: line(raw.caption, SHORT_TEXT, i, 'caption') };
      case 'videos':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            items: list(raw.items, MAX_SHELF, i, 'videos', (x) => ({
               kind: oneOf(x.kind, ['video', 'playlist', 'channel'] as const, 'video', i, 'kind'),
               ref_id: refId(x.ref_id, i, false),
               title_override: line(x.title_override, SHORT_TEXT, i, 'title'),
            })),
         };
      case 'posts': {
         const ids = raw.post_ids === undefined || raw.post_ids === null ? [] : raw.post_ids;
         if (!Array.isArray(ids)) throw new BlockError('bad_value', i, 'post_ids must be a list');
         if (ids.length > MAX_PICKED_POSTS) throw new BlockError('too_many_items', i, `at most ${MAX_PICKED_POSTS} posts can be picked`);
         const postIds = ids.map((x) => mediaId(x, i) ?? 0).filter((x) => x > 0);
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            mode: oneOf(raw.mode, ['latest', 'tag', 'picked'] as const, 'latest', i, 'mode'),
            limit: int(raw.limit, 3, 1, MAX_POSTS_LIMIT, i, 'the number of posts'),
            tag: line(raw.tag, 40, i, 'tag'),
            post_ids: [...new Set(postIds)],
         };
      }
      case 'cards':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            tag: line(raw.tag, 40, i, 'tag'),
            page_size: int(raw.page_size, 12, 3, MAX_CARDS_PAGE, i, 'cards per page'),
            filter: raw.filter === undefined ? true : raw.filter === true || raw.filter === 'true',
         };
      case 'stats':
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            heading: line(raw.heading, SHORT_TEXT, i, 'heading'),
            variant: oneOf(raw.variant, ['stats', 'features'] as const, 'features', i, 'style'),
            items: list(raw.items, MAX_STATS, i, 'items', (x) => ({
               value: line(x.value, STAT_VALUE, i, 'value'),
               label: line(x.label, SHORT_TEXT, i, 'label'),
               text: text(x.text, CARD_TEXT, i, 'text').trim(),
               icon: x.icon === undefined || x.icon === null || x.icon === '' ? '' : oneOf(x.icon, FEATURE_ICONS, 'star', i, 'icon'),
            })),
         };
      case 'divider':
         // v1 stored the line/space choice as `style` (a string); v2 keeps it as `style_kind`.
         return {
            id,
            type,
            appearance: styleOf(type, raw.appearance, i),
            style_kind: oneOf(raw.style_kind ?? (typeof raw.style === 'string' ? raw.style : undefined), ['line', 'space'] as const, 'line', i, 'style'),
            size: oneOf(raw.size, ['s', 'm', 'l'] as const, 'm', i, 'size'),
         };
      case 'contact': {
         const kind = oneOf(raw.kind, ['page', 'email'] as const, 'page', i, 'kind');
         const email = line(raw.email, 254, i, 'email');
         if (email && !validEmail(email)) throw new BlockError('bad_email', i, 'the email address is not valid');
         return { id, type, appearance: styleOf(type, raw.appearance, i), heading: line(raw.heading, SHORT_TEXT, i, 'heading'), text: text(raw.text, CTA_TEXT, i, 'text').trim(), label: line(raw.label, LABEL_TEXT, i, 'button label'), kind, email };
      }
   }
}

/** Validates and normalizes a page's blocks (unknown keys dropped, defaults filled). Throws BlockError. */
export function normalizePageBlocks(raw: unknown): PageBlock[] {
   const value = typeof raw === 'string' ? parseOrThrow(raw) : raw;
   if (value === null || value === undefined) return [];
   if (!Array.isArray(value)) throw new BlockError('not_list', null, 'blocks must be a list');
   if (value.length > MAX_BLOCKS) throw new BlockError('too_many', null, `a page can have at most ${MAX_BLOCKS} blocks`);
   const seen = new Set<string>();
   return value.map((b, i) => {
      const out = normalizeOne(b, i);
      if (seen.has(out.id)) throw new BlockError('duplicate_id', i, 'has the same id as another block');
      seen.add(out.id);
      return out;
   });
}

function parseOrThrow(s: string): unknown {
   try {
      return JSON.parse(s);
   } catch {
      throw new BlockError('not_list', null, 'blocks must be a list');
   }
}

/** Blocks as stored, without throwing (a malformed stored value reads as no blocks). */
export function storedPageBlocks(raw: unknown): PageBlock[] {
   try {
      return normalizePageBlocks(raw);
   } catch {
      return [];
   }
}

/**
 * Upgrades stored blocks of an older schema version to this one. v1 → v2 is lossless: every v1 block
 * is a valid v2 block once normalized (styles take the type's default; a divider's line/space moves
 * from `style` to `style_kind`; an image's size becomes its width).
 */
export function upgradePageBlocks(raw: unknown, _fromVersion: number | null): PageBlock[] {
   return normalizePageBlocks(raw);
}

/** True when the block has what it needs to show on the site. */
export function isBlockComplete(b: PageBlock): boolean {
   switch (b.type) {
      case 'hero':
         return (b.title !== '' || b.subtitle !== '') && (b.background !== 'image' || b.media_id !== null);
      case 'markdown':
         return b.text.trim() !== '';
      case 'image':
         return b.media_id !== null;
      case 'gallery':
         return b.items.some((x) => x.media_id !== null);
      case 'layout':
         return b.items.some((x) => x.heading !== '' || x.text.trim() !== '' || x.media_id !== null);
      case 'columns':
         return b.text.trim() !== '' || b.media_id !== null;
      case 'cardgrid':
         return b.items.some((x) => x.title !== '');
      case 'cta':
         return b.label !== '' && b.url !== '';
      case 'quote':
         return b.text !== '';
      case 'faq':
         return b.items.some((x) => x.q !== '' && x.a !== '');
      case 'video':
         return b.ref_id !== '';
      case 'videos':
         return b.items.length > 0;
      case 'posts':
         return b.mode === 'latest' || (b.mode === 'tag' ? b.tag !== '' : b.post_ids.length > 0);
      case 'cards':
      case 'divider':
         return true;
      case 'stats':
         return b.items.some((x) => x.label !== '');
      case 'contact':
         return b.label !== '' && (b.kind === 'page' || b.email !== '');
   }
}

/** One rich-text block holding a legacy body. */
export function bodyAsPageBlocks(body: unknown, id = 'body'): PageBlock[] {
   return typeof body === 'string' && body.trim() !== '' ? [{ id, type: 'markdown', appearance: DEFAULT_STYLE.markdown, text: body }] : [];
}

/** The site path of the contact page (www and the scholar sites); hosts map it like any "/…" link. */
export const CONTACT_PATH = '/contact/';

const mdLink = (label: string, href: string) => `[${label.replace(/[[\]]/g, '')}](${href})`;

/**
 * The markdown `body` kept beside the blocks for readers that predate blocks (meta descriptions, RSS,
 * the v1 fallback). Rich text is kept verbatim, so a page with one rich-text block has exactly its old
 * body. Media-only blocks are left out; an embedded video becomes a `::video[ID]` line.
 */
export function pageBlocksToMarkdown(blocks: PageBlock[]): string {
   const parts: string[] = [];
   const h = (s: string) => (s ? `## ${s}` : '');
   for (const b of blocks) {
      if (!isBlockComplete(b)) continue;
      switch (b.type) {
         case 'hero':
            parts.push([b.title ? `## ${b.title}` : '', b.subtitle, b.buttons.filter((x) => x.label && x.url).map((x) => mdLink(x.label, x.url)).join(' · ')].filter(Boolean).join('\n\n'));
            break;
         case 'markdown':
            parts.push(b.text.trim());
            break;
         case 'columns':
            if (b.text.trim()) parts.push(b.text.trim());
            break;
         case 'layout':
            for (const c of b.items) parts.push([c.heading ? `### ${c.heading}` : '', c.text.trim(), c.label && c.url ? mdLink(c.label, c.url) : ''].filter(Boolean).join('\n\n'));
            break;
         case 'cardgrid':
            parts.push([h(b.heading), b.intro, ...b.items.filter((x) => x.title).map((x) => [`### ${x.title}`, x.text, x.label && x.url ? mdLink(x.label, x.url) : ''].filter(Boolean).join('\n\n'))].filter(Boolean).join('\n\n'));
            break;
         case 'video':
            if (b.kind === 'video') parts.push(`::video[${b.ref_id}]`);
            break;
         case 'quote':
            parts.push([...b.text.split('\n').map((l) => `> ${l}`.trimEnd()), ...(b.cite ? ['>', `> — ${b.cite}`] : [])].join('\n'));
            break;
         case 'cta':
            parts.push([b.heading ? `**${b.heading}**` : '', b.text, mdLink(b.label, b.url)].filter(Boolean).join('\n\n'));
            break;
         case 'faq':
            parts.push([h(b.heading), ...b.items.filter((x) => x.q && x.a).map((x) => `**${x.q}**\n\n${x.a}`)].filter(Boolean).join('\n\n'));
            break;
         case 'stats':
            parts.push([h(b.heading), b.items.filter((x) => x.label).map((x) => `- ${[x.value, x.label].filter(Boolean).join(' ')}${x.text ? `: ${x.text.replace(/\s*\n\s*/g, ' ')}` : ''}`).join('\n')].filter(Boolean).join('\n\n'));
            break;
         case 'contact':
            parts.push([b.heading ? `**${b.heading}**` : '', b.text, mdLink(b.label, b.kind === 'email' ? `mailto:${b.email}` : CONTACT_PATH)].filter(Boolean).join('\n\n'));
            break;
         case 'divider':
            if (b.style_kind === 'line') parts.push('---');
            break;
         case 'posts':
         case 'cards':
         case 'videos':
            if (b.heading) parts.push(`## ${b.heading}`);
            break;
         case 'image':
         case 'gallery':
            break;
      }
   }
   return parts.filter(Boolean).join('\n\n');
}

/** Media library ids the blocks use. */
export function pageBlockMediaIds(blocks: PageBlock[]): number[] {
   const ids = new Set<number>();
   const add = (n: number | null) => n && ids.add(n);
   for (const b of blocks) {
      if (b.type === 'image' || b.type === 'columns' || b.type === 'hero') add(b.media_id);
      if (b.type === 'gallery' || b.type === 'layout' || b.type === 'cardgrid') for (const x of b.items) add(x.media_id);
   }
   return [...ids];
}

/** Videos-platform items the blocks use (shelves and embeds). */
export function pageBlockVideoRefs(blocks: PageBlock[]): { kind: ShelfKind; ref_id: string }[] {
   const out = new Map<string, { kind: ShelfKind; ref_id: string }>();
   for (const b of blocks) {
      if (b.type === 'video' && b.ref_id) out.set(`${b.kind}:${b.ref_id}`, { kind: b.kind, ref_id: b.ref_id });
      if (b.type === 'videos') for (const x of b.items) out.set(`${x.kind}:${x.ref_id}`, { kind: x.kind, ref_id: x.ref_id });
   }
   return [...out.values()];
}

/** Hand-picked post ids. */
export function pageBlockPostIds(blocks: PageBlock[]): number[] {
   return [...new Set(blocks.flatMap((b) => (b.type === 'posts' && b.mode === 'picked' ? b.post_ids : [])))];
}

/**
 * Every piece of reader-facing text in the blocks, with a stable path, so a translation helper can
 * translate a page and put the text back with `withPageBlockTexts`. `markdown: true` marks markdown
 * (keep `::video[ID]` lines and link targets as they are).
 */
export interface BlockText {
   path: string;
   value: string;
   markdown: boolean;
}

export function pageBlockTexts(blocks: PageBlock[]): BlockText[] {
   const out: BlockText[] = [];
   const add = (path: string, value: string, markdown = false) => {
      if (value.trim()) out.push({ path, value, markdown });
   };
   for (const b of blocks) {
      const p = b.id;
      switch (b.type) {
         case 'hero':
            add(`${p}.eyebrow`, b.eyebrow);
            add(`${p}.title`, b.title);
            add(`${p}.subtitle`, b.subtitle);
            add(`${p}.alt`, b.alt);
            b.buttons.forEach((x, j) => add(`${p}.buttons.${j}.label`, x.label));
            break;
         case 'markdown':
            add(`${p}.text`, b.text, true);
            break;
         case 'image':
            add(`${p}.alt`, b.alt);
            add(`${p}.caption`, b.caption);
            break;
         case 'gallery':
            b.items.forEach((x, j) => {
               add(`${p}.items.${j}.alt`, x.alt);
               add(`${p}.items.${j}.caption`, x.caption);
            });
            break;
         case 'layout':
            b.items.forEach((x, j) => {
               add(`${p}.items.${j}.heading`, x.heading);
               add(`${p}.items.${j}.text`, x.text, true);
               add(`${p}.items.${j}.label`, x.label);
               add(`${p}.items.${j}.alt`, x.alt);
            });
            break;
         case 'columns':
            add(`${p}.text`, b.text, true);
            add(`${p}.alt`, b.alt);
            add(`${p}.caption`, b.caption);
            break;
         case 'cardgrid':
            add(`${p}.heading`, b.heading);
            add(`${p}.intro`, b.intro);
            b.items.forEach((x, j) => {
               add(`${p}.items.${j}.title`, x.title);
               add(`${p}.items.${j}.text`, x.text);
               add(`${p}.items.${j}.label`, x.label);
               add(`${p}.items.${j}.alt`, x.alt);
            });
            break;
         case 'cta':
            add(`${p}.heading`, b.heading);
            add(`${p}.text`, b.text);
            add(`${p}.label`, b.label);
            break;
         case 'quote':
            add(`${p}.text`, b.text);
            add(`${p}.cite`, b.cite);
            break;
         case 'faq':
            add(`${p}.heading`, b.heading);
            b.items.forEach((x, j) => {
               add(`${p}.items.${j}.q`, x.q);
               add(`${p}.items.${j}.a`, x.a, true);
            });
            break;
         case 'video':
            add(`${p}.caption`, b.caption);
            break;
         case 'videos':
            add(`${p}.heading`, b.heading);
            b.items.forEach((x, j) => add(`${p}.items.${j}.title_override`, x.title_override));
            break;
         case 'posts':
         case 'cards':
            add(`${p}.heading`, b.heading);
            break;
         case 'stats':
            add(`${p}.heading`, b.heading);
            b.items.forEach((x, j) => {
               add(`${p}.items.${j}.value`, x.value);
               add(`${p}.items.${j}.label`, x.label);
               add(`${p}.items.${j}.text`, x.text, true);
            });
            break;
         case 'contact':
            add(`${p}.heading`, b.heading);
            add(`${p}.text`, b.text);
            add(`${p}.label`, b.label);
            break;
         case 'divider':
            break;
      }
   }
   return out;
}

/** A copy of `blocks` with the texts at `paths` replaced (unknown paths are ignored). Re-normalized. */
export function withPageBlockTexts(blocks: PageBlock[], texts: Record<string, string>): PageBlock[] {
   const copy = JSON.parse(JSON.stringify(blocks)) as Obj[];
   const byId = new Map(copy.map((b) => [String(b.id), b]));
   for (const [path, value] of Object.entries(texts)) {
      const [id, ...rest] = path.split('.');
      let target: unknown = byId.get(id ?? '');
      for (const key of rest.slice(0, -1)) target = isObj(target) || Array.isArray(target) ? (target as Obj)[key] : undefined;
      const last = rest.at(-1);
      if (last && isObj(target) && typeof target[last] === 'string') target[last] = value;
   }
   return normalizePageBlocks(copy);
}

/** A fresh, empty block of `type` (the editor's starting values). */
export function emptyPageBlock(type: PageBlockType, id = newBlockId()): PageBlock {
   return normalizeOne({ id, type }, 0);
}

/**
 * The block picker's presets: one entry per card in the picker. Several presets share a type with
 * different starting values (a CTA band is a call to action at full width; three columns is a layout
 * with three empty columns). `group` orders the picker.
 */
export const PAGE_BLOCK_PRESETS = [
   { key: 'hero', group: 'layout', type: 'hero', init: { buttons: [{ label: '', url: '', variant: 'primary' }] } },
   { key: 'layout2', group: 'layout', type: 'layout', init: { columns: 2, items: [{}, {}] } },
   { key: 'layout3', group: 'layout', type: 'layout', init: { columns: 3, items: [{}, {}, {}] } },
   { key: 'columns', group: 'layout', type: 'columns', init: {} },
   { key: 'divider', group: 'layout', type: 'divider', init: {} },
   { key: 'spacer', group: 'layout', type: 'divider', init: { style_kind: 'space' } },
   { key: 'markdown', group: 'basic', type: 'markdown', init: {} },
   { key: 'image', group: 'basic', type: 'image', init: {} },
   { key: 'gallery', group: 'basic', type: 'gallery', init: {} },
   { key: 'quote', group: 'basic', type: 'quote', init: {} },
   { key: 'cardgrid', group: 'sections', type: 'cardgrid', init: { items: [{}, {}, {}] } },
   { key: 'features', group: 'sections', type: 'stats', init: { variant: 'features', items: [{ icon: 'play' }, { icon: 'users' }, { icon: 'globe' }] } },
   { key: 'stats', group: 'sections', type: 'stats', init: { variant: 'stats', items: [{}, {}, {}] } },
   { key: 'faq', group: 'sections', type: 'faq', init: { items: [{}, {}] } },
   { key: 'cta', group: 'sections', type: 'cta', init: {} },
   { key: 'ctaband', group: 'sections', type: 'cta', init: { appearance: { width: 'full', tone: 'night', align: 'center' } } },
   { key: 'contact', group: 'sections', type: 'contact', init: {} },
   { key: 'video', group: 'media', type: 'video', init: {} },
   { key: 'videos', group: 'media', type: 'videos', init: {} },
   { key: 'posts', group: 'media', type: 'posts', init: {} },
   { key: 'cards', group: 'media', type: 'cards', init: {} },
] as const satisfies readonly { key: string; group: 'layout' | 'basic' | 'sections' | 'media'; type: PageBlockType; init: Obj }[];
export type PageBlockPreset = (typeof PAGE_BLOCK_PRESETS)[number];
export type PresetKey = PageBlockPreset['key'];

/** A new block from a picker preset. */
export function presetBlock(key: PresetKey, id = newBlockId()): PageBlock {
   const p = PAGE_BLOCK_PRESETS.find((x) => x.key === key);
   if (!p) throw new BlockError('bad_type', 0, 'is not a known block type');
   return normalizeOne({ ...JSON.parse(JSON.stringify(p.init)), id, type: p.type }, 0);
}

/* ════════════════════════════════════════════════════════════════════════════════════════════════
 * 2. Served schema (public API) and the stored → served mapping
 * ════════════════════════════════════════════════════════════════════════════════════════════════ */

/** A library image as served (CMS media-ref): `variants` are resized copies (srcset strings). */
export interface MediaRef {
   url: string;
   alt: string | null;
   width: number | null;
   height: number | null;
   variants?: { widths: number[]; fallback_type: string; avif: string; webp: string; fallback: string } | null;
}

/** What the CMS keeps about a videos-platform item (CuratedSnapshot in the public API). */
export interface VideoSnapshot {
   title: string;
   thumbnail_url: string | null;
   channel_name: string | null;
   duration_seconds?: number | null;
   titles?: { en?: string; ar?: string };
   [k: string]: unknown;
}

/** A post as listed (PostSummary in the public API); only the fields the renderer reads are typed. */
export interface PostSummaryLite {
   slug: string;
   locale: 'en' | 'ar';
   title: string;
   excerpt: string | null;
   cover: MediaRef | null;
   published_at: string;
   kind?: 'article' | 'cards';
   first_slide?: { image: MediaRef } | null;
   author_name?: string | null;
   [k: string]: unknown;
}

type S<T extends string, F> = { id: string; type: T; appearance: BlockStyle } & F;
export type ServedBlock =
   | S<'hero', { eyebrow: string | null; title: string | null; subtitle: string | null; background: 'gradient' | 'image' | 'plain'; image: MediaRef | null; height: 's' | 'm' | 'l'; buttons: { label: string; url: string; variant: 'primary' | 'secondary' }[] }>
   | S<'markdown', { text: string }>
   | S<'image', { image: MediaRef; caption: string | null; size: 'content' | 'wide' }>
   | S<'gallery', { columns: 2 | 3 | 4; items: { image: MediaRef; caption: string | null }[] }>
   | S<'layout', { columns: 2 | 3; items: { image: MediaRef | null; heading: string | null; text: string | null; label: string | null; url: string | null }[] }>
   | S<'columns', { text: string; image: MediaRef | null; caption: string | null; image_side: 'start' | 'end' }>
   | S<'cardgrid', { heading: string | null; intro: string | null; columns: 2 | 3 | 4; items: { image: MediaRef | null; title: string; text: string | null; label: string | null; url: string | null }[] }>
   | S<'cta', { heading: string | null; text: string | null; label: string; url: string; tone: 'primary' | 'quiet' }>
   | S<'quote', { variant: 'quote' | 'callout'; text: string; cite: string | null }>
   | S<'faq', { heading: string | null; items: { q: string; a: string }[] }>
   | S<'video', { kind: 'video' | 'playlist'; ref_id: string; caption: string | null; snapshot: VideoSnapshot | null }>
   | S<'videos', { heading: string | null; items: { kind: ShelfKind; ref_id: string; title_override: string | null; snapshot: VideoSnapshot | null }[] }>
   | S<'posts', { heading: string | null; mode: 'latest' | 'tag' | 'picked'; items: PostSummaryLite[] }>
   | S<'cards', { heading: string | null; tag: string | null; page_size: number; filter: boolean }>
   | S<'stats', { heading: string | null; variant: 'stats' | 'features'; items: { value: string | null; label: string; text: string | null; icon: FeatureIcon | null }[] }>
   | S<'divider', { style_kind: 'line' | 'space'; size: 's' | 'm' | 'l'; /** v1 readers: the same as style_kind. */ style: 'line' | 'space' }>
   | S<'contact', { heading: string | null; text: string | null; label: string; href: string }>;

export type ServedBlockOf<T extends PageBlockType> = Extract<ServedBlock, { type: T }>;

/** Lookups `servePageBlocks` needs, prefetched by the caller (D1 in the CMS, editor state in the preview). */
export interface ServeRefs {
   /** A library image by id, or null when it is gone / not an image. */
   media: (id: number) => MediaRef | null | undefined;
   /** A videos-platform snapshot; `undefined` = no longer public (the item is left out), null = not yet taken. */
   snapshot: (kind: string, refId: string) => VideoSnapshot | null | undefined;
   /** The posts a `posts` block lists, already resolved for the page's locale. */
   posts: (b: PageBlockOf<'posts'>) => PostSummaryLite[];
}

const orNull = (s: string) => (s.trim() ? s : null);

/**
 * Stored blocks → served blocks. Incomplete blocks are left out, and so is a block whose references
 * are all gone, so no host ever renders an empty frame. The block's own alt text wins over the
 * library's. Strictly additive over v1 (the public API contract www checks): every block gains
 * `appearance`; v1 fields stay as they were (image `size`, and a divider's `style` string, which v2
 * readers take from `style_kind`).
 */
export function servePageBlocks(blocks: PageBlock[], refs: ServeRefs): ServedBlock[] {
   const img = (id: number | null, alt: string): MediaRef | null => {
      const ref = id ? refs.media(id) : null;
      return ref ? { ...ref, alt: alt.trim() ? alt : ref.alt } : null;
   };
   const out: ServedBlock[] = [];
   for (const b of blocks) {
      if (!isBlockComplete(b)) continue;
      const base = { id: b.id, appearance: b.appearance };
      switch (b.type) {
         case 'hero': {
            const image = b.background === 'image' ? img(b.media_id, b.alt) : null;
            out.push({
               ...base,
               type: 'hero',
               eyebrow: orNull(b.eyebrow),
               title: orNull(b.title),
               subtitle: orNull(b.subtitle),
               background: b.background === 'image' && !image ? 'gradient' : b.background,
               image,
               height: b.height,
               buttons: b.buttons.filter((x) => x.label && x.url),
            });
            break;
         }
         case 'markdown':
            out.push({ ...base, type: 'markdown', text: b.text });
            break;
         case 'image': {
            const image = img(b.media_id, b.alt);
            if (image) out.push({ ...base, type: 'image', image, caption: orNull(b.caption), size: b.size });
            break;
         }
         case 'gallery': {
            const items = b.items.flatMap((x) => {
               const image = img(x.media_id, x.alt);
               return image ? [{ image, caption: orNull(x.caption) }] : [];
            });
            if (items.length) out.push({ ...base, type: 'gallery', columns: b.columns, items });
            break;
         }
         case 'layout': {
            const items = b.items.map((x) => ({ image: img(x.media_id, x.alt), heading: orNull(x.heading), text: orNull(x.text), label: x.label && x.url ? x.label : null, url: x.label && x.url ? x.url : null }));
            out.push({ ...base, type: 'layout', columns: b.columns, items });
            break;
         }
         case 'columns': {
            const image = img(b.media_id, b.alt);
            out.push({ ...base, type: 'columns', text: b.text, image, caption: image ? orNull(b.caption) : null, image_side: b.image_side });
            break;
         }
         case 'cardgrid': {
            const items = b.items.filter((x) => x.title).map((x) => ({ image: img(x.media_id, x.alt), title: x.title, text: orNull(x.text), label: x.url ? orNull(x.label) : null, url: x.url || null }));
            out.push({ ...base, type: 'cardgrid', heading: orNull(b.heading), intro: orNull(b.intro), columns: b.columns, items });
            break;
         }
         case 'cta':
            out.push({ ...base, type: 'cta', heading: orNull(b.heading), text: orNull(b.text), label: b.label, url: b.url, tone: b.tone });
            break;
         case 'quote':
            out.push({ ...base, type: 'quote', variant: b.variant, text: b.text, cite: orNull(b.cite) });
            break;
         case 'faq':
            out.push({ ...base, type: 'faq', heading: orNull(b.heading), items: b.items.filter((x) => x.q && x.a) });
            break;
         case 'video': {
            const snapshot = refs.snapshot(b.kind, b.ref_id);
            if (snapshot !== undefined) out.push({ ...base, type: 'video', kind: b.kind, ref_id: b.ref_id, caption: orNull(b.caption), snapshot });
            break;
         }
         case 'videos': {
            const items = b.items.flatMap((x) => {
               const snapshot = refs.snapshot(x.kind, x.ref_id);
               return snapshot === undefined ? [] : [{ kind: x.kind, ref_id: x.ref_id, title_override: orNull(x.title_override), snapshot }];
            });
            if (items.length) out.push({ ...base, type: 'videos', heading: orNull(b.heading), items });
            break;
         }
         case 'posts': {
            const items = refs.posts(b);
            if (items.length) out.push({ ...base, type: 'posts', heading: orNull(b.heading), mode: b.mode, items });
            break;
         }
         case 'cards':
            out.push({ ...base, type: 'cards', heading: orNull(b.heading), tag: orNull(b.tag), page_size: b.page_size, filter: b.filter });
            break;
         case 'stats':
            out.push({ ...base, type: 'stats', heading: orNull(b.heading), variant: b.variant, items: b.items.filter((x) => x.label).map((x) => ({ value: orNull(x.value), label: x.label, text: orNull(x.text), icon: x.icon || null })) });
            break;
         case 'divider':
            out.push({ ...base, type: 'divider', style: b.style_kind, style_kind: b.style_kind, size: b.size });
            break;
         case 'contact':
            out.push({ ...base, type: 'contact', heading: orNull(b.heading), text: orNull(b.text), label: b.label, href: b.kind === 'email' ? `mailto:${b.email}` : CONTACT_PATH });
            break;
      }
   }
   return out;
}

/* ════════════════════════════════════════════════════════════════════════════════════════════════
 * 3. Renderer
 * ════════════════════════════════════════════════════════════════════════════════════════════════ */

const ESC: Record<string, string> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
/** Escapes text for HTML content and double-quoted attributes. */
export const esc = (s: unknown): string => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c] ?? c);

/** A served block straight from the network: is it shaped enough to render? (defence in depth) */
const str = (v: unknown): v is string => typeof v === 'string';

export interface ImageOptions {
   /** The `sizes` attribute for the layout slot. */
   sizes: string;
   /** The page's LCP image: eager, high priority. */
   priority: boolean;
   className?: string;
}

export interface RenderContext {
   /** The page's language (every block's text is in it). */
   locale: 'en' | 'ar';
   /** The page title: a first-block hero with no title of its own shows it. */
   pageTitle?: string;
   /**
    * The first block is a hero and the host shows no page header of its own: the hero's title is the
    * page's h1. Default: true when the first block is a hero (see `leadsWithHero`).
    */
   heroIsPageHeading?: boolean;
   /** The page has a cover/LCP image above the blocks (no block image gets priority then). */
   hasCover?: boolean;
   /** A stored link ("/…" site path or https) → the href to write, or null to drop the link. Default: as is. */
   href?: (url: string) => string | null;
   /** Trusted HTML for an image (www: responsive <picture>). Default: <img> with srcset from variants. */
   image?: (ref: MediaRef, o: ImageOptions) => string;
   /** Trusted HTML for markdown (www: its body renderer with video facades). null → the built-in renderer. */
   markdown?: (text: string, blockId: string) => string | null;
   /** Trusted HTML for an embedded video. null → the built-in facade (a link to the watch page). */
   video?: (b: ServedBlockOf<'video'>) => string | null;
   /** The watch page of a videos-platform item (the built-in facade and shelf link to it). */
   watchHref?: (kind: ShelfKind, refId: string) => string | null;
   /** A listed post's page. Default: `/{locale}/articles/{slug}/` through `href`. */
   postHref?: (post: PostSummaryLite) => string | null;
   /** Trusted HTML for any block, replacing the built-in rendering (e.g. www's paged card-post grid). */
   slot?: (b: ServedBlock) => string | null;
}

/** True when the page's first block is a hero (the host should leave out its own page header). */
export function leadsWithHero(blocks: readonly { type: string }[]): boolean {
   return blocks[0]?.type === 'hero';
}

const T = {
   en: { play: 'Play', playlist: 'Playlist', videos: 'videos', minutes: 'min', read: 'Read', email: 'Email' },
   ar: { play: 'تشغيل', playlist: 'قائمة تشغيل', videos: 'مرئيات', minutes: 'د', read: 'اقرأ', email: 'البريد' },
} as const;

/* ── Icons ──────────────────────────────────────────────────────────────────────────────────────── */

