/** A decorative stroke icon (aria-hidden). `fill` for the quote mark and the play triangle. */
export function iconSvg(name: keyof typeof ICON_PATHS, cls = 'pb-ic'): string {
   const filled = name === 'quote' || name === 'playFill';
   return `<svg class="${cls}" viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false"${filled ? ' fill="currentColor" stroke="none"' : ' fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"'}><path d="${ICON_PATHS[name]}"/></svg>`;
}

/* ── Built-in safe markdown (headings, paragraphs, lists, quotes, rules, bold, italic, links) ─────── */

/*
 * Inline patterns, sticky (matched at lastIndex, no slicing) and bounded (a span is at most 600
 * characters), so a long paragraph is linear: patterns are only tried at `*`, `_`, a backtick or `[`.
 */
const IL_BOLD = /\*\*([^*\n]{1,600}?)\*\*/y;
const IL_EM = /\*([^*\s][^*\n]{0,600}?)\*/y;
const IL_EM2 = /_([^_\s][^_\n]{0,600}?)_(?![\p{L}\p{N}])/uy;
const IL_CODE = /`([^`\n]{1,600})`/y;
const IL_LINK = /\[([^[\]\n]{1,600})\]\(([^()\s]{1,2048})\)/y;
const at = (re: RegExp, s: string, i: number): RegExpExecArray | null => {
   re.lastIndex = i;
   return re.exec(s);
};

/** Inline markdown: **bold**, *italic*, `code`, [label](href). Everything else is text. */
/** A regex match group, '' when it did not take part (strict index access). */
const g = (m: RegExpMatchArray, i: number): string => m[i] ?? '';

export function inlineMarkdown(s: string, href: (u: string) => string | null): string {
   let out = '';
   let text = 0;
   let i = 0;
   const flush = (to: number) => {
      if (to > text) out += esc(s.slice(text, to));
   };
   while (i < s.length) {
      const ch = s.charCodeAt(i);
      // * _ ` [
      if (ch !== 42 && ch !== 95 && ch !== 96 && ch !== 91) {
         i += 1;
         continue;
      }
      let m: RegExpExecArray | null = null;
      let html = '';
      if (ch === 42 && (m = at(IL_BOLD, s, i))) html = `<strong>${inlineMarkdown(g(m, 1), href)}</strong>`;
      else if (ch === 42 && (m = at(IL_EM, s, i))) html = `<em>${inlineMarkdown(g(m, 1), href)}</em>`;
      else if (ch === 95 && (i === 0 || !/[\p{L}\p{N}]/u.test(s.charAt(i - 1))) && (m = at(IL_EM2, s, i))) html = `<em>${inlineMarkdown(g(m, 1), href)}</em>`;
      else if (ch === 96 && (m = at(IL_CODE, s, i))) html = `<code>${esc(m[1])}</code>`;
      else if (ch === 91 && (m = at(IL_LINK, s, i))) {
         const target = safeHref(g(m, 2), href);
         html = target ? `<a href="${esc(target)}"${/^https:/i.test(target) ? ' rel="noopener"' : ''}>${inlineMarkdown(g(m, 1), href)}</a>` : inlineMarkdown(g(m, 1), href);
      }
      if (!m) {
         i += 1;
         continue;
      }
      flush(i);
      out += html;
      i += m[0].length;
      text = i;
   }
   flush(s.length);
   return out;
}

/** A link target the page may write: "/…" and https through the host's mapper, mailto as is. Else null. */
function safeHref(u: string, href: (u: string) => string | null): string | null {
   if (/^mailto:/i.test(u)) return validEmail(u.slice(7)) ? u : null;
   if (!validBlockUrl(u)) return null;
   return href(u);
}

/**
 * Block markdown → HTML. Safe by construction: every character of text goes through `esc`; only the
 * tags below are written. `::video[ID]` lines are handed to `video` (or dropped). Raw HTML is text.
 */
export function blockMarkdown(md: string, href: (u: string) => string | null, video?: (id: string) => string | null, headingBase = 2): string {
   const lines = md.replace(/\r\n?/g, '\n').split('\n');
   const out: string[] = [];
   let para: string[] = [];
   let listKind: 'ul' | 'ol' | null = null;
   let items: string[] = [];
   let quote: string[] = [];
   const flushPara = () => {
      if (para.length) out.push(`<p>${inlineMarkdown(para.join(' '), href)}</p>`);
      para = [];
   };
   const flushList = () => {
      if (listKind) out.push(`<${listKind}>${items.map((x) => `<li>${inlineMarkdown(x, href)}</li>`).join('')}</${listKind}>`);
      listKind = null;
      items = [];
   };
   const flushQuote = () => {
      if (quote.length) out.push(`<blockquote>${blockMarkdown(quote.join('\n'), href, video, headingBase)}</blockquote>`);
      quote = [];
   };
   const flushAll = () => {
      flushPara();
      flushList();
      flushQuote();
   };
   for (const raw of lines) {
      const l = raw.trimEnd();
      let m: RegExpMatchArray | null;
      if (/^\s*>/.test(l)) {
         flushPara();
         flushList();
         quote.push(l.replace(/^\s*>\s?/, ''));
         continue;
      }
      if (quote.length) flushQuote();
      if (!l.trim()) {
         flushPara();
         flushList();
         continue;
      }
      if ((m = l.match(/^::video\[([A-Za-z0-9_-]{1,128})\]\s*$/))) {
         flushAll();
         const v = video?.(g(m, 1));
         if (v) out.push(v);
         continue;
      }
      if ((m = l.match(/^(#{1,4})[ \t]+(\S.*)$/))) {
         flushAll();
         const level = Math.min(6, Math.max(headingBase, g(m, 1).length + headingBase - 2));
         // Closing #s ("## Title ##") go, by scanning back (a trailing-space regex is quadratic).
         let title = g(m, 2);
         let j = title.length;
         while (j > 0 && title.charAt(j - 1) === '#') j -= 1;
         if (j < title.length && j > 0 && (title.charAt(j - 1) === ' ' || title.charAt(j - 1) === '\t')) title = title.slice(0, j);
         title = title.trim();
         out.push(`<h${level}>${inlineMarkdown(title, href)}</h${level}>`);
         continue;
      }
      if (/^\s*([-*_])(\s*\1){2,}\s*$/.test(l)) {
         flushAll();
         out.push('<hr>');
         continue;
      }
      if ((m = l.match(/^\s*[-*+]\s+(.+)$/)) || (m = l.match(/^\s*\d{1,3}[.)]\s+(.+)$/))) {
         flushPara();
         const kind = /^\s*\d/.test(l) ? 'ol' : 'ul';
         if (listKind && listKind !== kind) flushList();
         listKind = kind;
         items.push(g(m, 1));
         continue;
      }
      if (listKind && /^\s{2,}\S/.test(raw)) {
         items[items.length - 1] += ` ${l.trim()}`;
         continue;
      }
      flushList();
      para.push(l.trim());
   }
   flushAll();
   return out.join('');
}

/* ── Pieces ─────────────────────────────────────────────────────────────────────────────────────── */

const SIZES = {
   content: '(min-width: 48rem) 44rem, calc(100vw - 2rem)',
   wide: '(min-width: 78rem) 74rem, calc(100vw - 2rem)',
   full: '100vw',
   card: (cols: number) => `(min-width: 78rem) ${Math.round(74 / cols)}rem, (min-width: 40rem) 50vw, calc(100vw - 2rem)`,
   half: '(min-width: 60rem) 36rem, calc(100vw - 2rem)',
} as const;

/** The built-in <img>: width/height reserve the box; srcset from the CMS variants when present. */
export function defaultImage(ref: MediaRef, o: ImageOptions): string {
   const v = ref.variants;
   // Only whole positive numbers reach the markup: served data is checked, never trusted.
   const px = (n: unknown): n is number => typeof n === 'number' && Number.isInteger(n) && n > 0 && n <= 20_000;
   const dims = px(ref.width) && px(ref.height) ? ` width="${ref.width}" height="${ref.height}"` : '';
   const srcset = v && v.webp ? ` srcset="${esc(v.webp)}" sizes="${esc(o.sizes)}"` : '';
   const load = o.priority ? ' loading="eager" fetchpriority="high"' : ' loading="lazy"';
   return `<img${o.className ? ` class="${esc(o.className)}"` : ''} src="${esc(ref.url)}"${srcset} alt="${esc(ref.alt ?? '')}"${dims}${load} decoding="async">`;
}

function fmtDuration(sec: number | null | undefined): string | null {
   if (typeof sec !== 'number' || !Number.isFinite(sec) || sec <= 0) return null;
   const s = Math.round(sec);
   const h = Math.floor(s / 3600);
   const m = Math.floor((s % 3600) / 60);
   const ss = String(s % 60).padStart(2, '0');
   return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`;
}

function fmtDate(iso: string, locale: 'en' | 'ar'): string | null {
   const d = new Date(iso);
   if (Number.isNaN(d.getTime())) return null;
   try {
      return new Intl.DateTimeFormat(locale === 'ar' ? 'ar' : 'en', { year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' }).format(d);
   } catch {
      return iso.slice(0, 10);
   }
}

/* ── The renderer ───────────────────────────────────────────────────────────────────────────────── */

/**
 * Served blocks → HTML (the `.pb` root and one section per block). Unknown or malformed blocks are
 * skipped. The root carries the page's lang and dir; logical CSS properties make it mirror in RTL.
 * The host places the root at full page width (no reading-column wrapper): blocks set their own widths.
 */
export function renderPageBlocks(blocks: readonly unknown[], ctx: RenderContext): string {
   const L = ctx.locale === 'ar' ? 'ar' : 'en';
   const t = T[L];
   const href = (u: string): string | null => (validBlockUrl(u) ? (ctx.href ? ctx.href(u) : u) : null);
   const image = (ref: MediaRef | null | undefined, o: ImageOptions): string => (ref && str(ref.url) ? (ctx.image ?? defaultImage)(ref, o) : '');
   const list = (Array.isArray(blocks) ? blocks : []).filter((b): b is ServedBlock => isObj(b) && str(b.id) && BLOCK_ID.test(b.id) && PAGE_BLOCK_TYPES.includes(b.type as PageBlockType)).slice(0, MAX_BLOCKS);
   const heroH1 = ctx.heroIsPageHeading ?? leadsWithHero(list);
   let lcp = !!ctx.hasCover;
   const takeLcp = () => (lcp ? false : ((lcp = true), true));
   const md = (text: string, id: string, base = 2) => ctx.markdown?.(text, id) ?? blockMarkdown(text, href, (vid) => videoFacade({ kind: 'video', ref_id: vid, snapshot: null, caption: null }), base);
   const watch = (kind: ShelfKind, ref: string) => ctx.watchHref?.(kind, ref) ?? null;
   const titleOf = (s: VideoSnapshot | null, fallback: string) => (s && ((L === 'ar' ? s.titles?.ar : s.titles?.en) || s.title)) || fallback;

   function videoFacade(b: { kind: 'video' | 'playlist'; ref_id: string; snapshot: VideoSnapshot | null; caption: string | null }): string {
      const link = watch(b.kind, b.ref_id);
      const title = titleOf(b.snapshot, '');
      const thumb = b.snapshot?.thumbnail_url;
      const dur = b.kind === 'video' ? fmtDuration(b.snapshot?.duration_seconds) : null;
      const inner = `<span class="pb-vthumb">${thumb ? `<img src="${esc(thumb)}" alt="" loading="lazy" decoding="async" width="640" height="360">` : ''}<span class="pb-play">${iconSvg('playFill', 'pb-play-ic')}<span class="pb-sr">${esc(t.play)}</span></span>${dur ? `<span class="pb-dur">${esc(dur)}</span>` : ''}${b.kind === 'playlist' ? `<span class="pb-dur">${esc(t.playlist)}</span>` : ''}</span>${title ? `<span class="pb-vtitle">${esc(title)}</span>` : ''}`;
      // Named by its own text ("Play", duration, title): an aria-label would hide the visible words (WCAG 2.5.3).
      return link ? `<a class="pb-facade" href="${esc(link)}">${inner}</a>` : `<div class="pb-facade">${inner}</div>`;
   }

   const button = (label: string, u: string, variant: string) => {
      const h = href(u);
      return h ? `<a class="pb-btn pb-btn-${variant}" href="${esc(h)}"${/^https:/i.test(h) ? ' rel="noopener"' : ''}>${esc(label)}</a>` : '';
   };
   const heading = (id: string, s: string | null, cls = 'pb-heading') => (s ? `<h2 class="${cls}" id="pb-${esc(id)}-h">${esc(s)}</h2>` : '');
   const section = (b: ServedBlock, inner: string, opts: { cls?: string; labelled?: boolean; tag?: string; bg?: string } = {}) => {
      const st = b.appearance && isObj(b.appearance) ? b.appearance : DEFAULT_STYLE[b.type];
      const w = WIDTHS.includes(st.width) ? st.width : 'content';
      const tone = TONES.includes(st.tone) ? st.tone : 'none';
      const a = ALIGNS.includes(st.align) ? st.align : 'start';
      const sp = SPACES.includes(st.space) ? st.space : 'm';
      const tag = opts.tag ?? 'section';
      const cls = `pb-b pb-k-${b.type} pb-w-${w} pb-t-${tone} pb-a-${a} pb-s-${sp}${opts.cls ? ` ${opts.cls}` : ''}`;
      return `<${tag} class="${cls}" data-block="${esc(b.id)}" data-block-type="${b.type}"${opts.labelled ? ` aria-labelledby="pb-${esc(b.id)}-h"` : ''}>${opts.bg ?? ''}<div class="pb-in">${inner}</div></${tag}>`;
   };

   const html: string[] = [];
   list.forEach((b, index) => {
      const own = ctx.slot?.(b);
      if (own) return void html.push(own);
      try {
         html.push(renderOne(b, index));
      } catch {
         /* a malformed served block renders nothing, never a broken page */
      }
   });
   return `<div class="pb" lang="${L}" dir="${L === 'ar' ? 'rtl' : 'ltr'}">${html.join('')}</div>`;

   function renderOne(b: ServedBlock, index: number): string {
      switch (b.type) {
         case 'hero': {
            const isH1 = heroH1 && index === 0;
            const title = b.title ?? (isH1 ? ctx.pageTitle ?? null : null);
            const H = isH1 ? 'h1' : 'h2';
            const bgKind = b.background === 'image' && b.image ? 'image' : b.background === 'plain' ? 'plain' : 'gradient';
            const bg =
               bgKind === 'image'
                  ? `<div class="pb-hero-media">${image(b.image, { sizes: SIZES.full, priority: takeLcp(), className: 'pb-hero-img' })}</div><div class="pb-hero-scrim" aria-hidden="true"></div>`
                  : bgKind === 'gradient'
                    ? '<div class="pb-hero-glow" aria-hidden="true"></div><div class="pb-hero-pattern" aria-hidden="true"></div>'
                    : '';
            const buttons = (Array.isArray(b.buttons) ? b.buttons : []).slice(0, MAX_HERO_BUTTONS).map((x) => button(x.label, x.url, x.variant === 'secondary' ? 'ghost' : 'primary')).join('');
            const inner = `<div class="pb-hero-copy">${b.eyebrow ? `<p class="pb-eyebrow">${esc(b.eyebrow)}</p>` : ''}${title ? `<${H} class="pb-hero-title" id="pb-${esc(b.id)}-h">${esc(title)}</${H}>` : ''}${b.subtitle ? `<p class="pb-hero-sub">${esc(b.subtitle)}</p>` : ''}${buttons ? `<div class="pb-actions">${buttons}</div>` : ''}</div>`;
            return section(b, inner, { cls: `pb-hero-${bgKind} pb-h-${['s', 'm', 'l'].includes(b.height) ? b.height : 'm'}`, labelled: !!title, bg });
         }
         case 'markdown': {
            const body = md(String(b.text ?? ''), b.id);
            return body.trim() ? section(b, `<div class="pb-prose">${body}</div>`, { tag: 'div' }) : '';
         }
         case 'image': {
            const w = b.appearance?.width ?? (b.size === 'wide' ? 'wide' : 'content');
            const pic = image(b.image, { sizes: SIZES[w === 'full' ? 'full' : w === 'wide' ? 'wide' : 'content'], priority: takeLcp(), className: 'pb-img' });
            return pic ? section(b, `<figure class="pb-figure">${pic}${b.caption ? `<figcaption>${esc(b.caption)}</figcaption>` : ''}</figure>`, { tag: 'div' }) : '';
         }
         case 'gallery': {
            const cols = [2, 3, 4].includes(b.columns) ? b.columns : 3;
            const items = (b.items ?? []).map((x) => {
               const pic = image(x.image, { sizes: SIZES.card(cols), priority: false, className: 'pb-img' });
               return pic ? `<li><figure class="pb-figure">${pic}${x.caption ? `<figcaption>${esc(x.caption)}</figcaption>` : ''}</figure></li>` : '';
            });
            return items.some(Boolean) ? section(b, `<ul class="pb-gallery pb-cols-${cols}" role="list">${items.join('')}</ul>`, { tag: 'div' }) : '';
         }
         case 'layout': {
            const cols = b.columns === 3 ? 3 : 2;
            const items = (b.items ?? []).slice(0, cols).map((c) => {
               const pic = image(c.image, { sizes: SIZES.card(cols), priority: false, className: 'pb-img' });
               const link = c.label && c.url ? href(c.url) : null;
               return `<div class="pb-col">${pic ? `<div class="pb-col-media">${pic}</div>` : ''}${c.heading ? `<h3 class="pb-col-h">${esc(c.heading)}</h3>` : ''}${c.text ? `<div class="pb-prose">${md(c.text, b.id, 3)}</div>` : ''}${link ? `<a class="pb-more" href="${esc(link)}"${/^https:/i.test(link) ? ' rel="noopener"' : ''}>${esc(c.label)}${iconSvg('arrow', 'pb-ic pb-flip')}</a>` : ''}</div>`;
            });
            return section(b, `<div class="pb-layout pb-cols-${cols}">${items.join('')}</div>`, { tag: 'div' });
         }
         case 'columns': {
            const body = md(String(b.text ?? ''), b.id);
            const pic = image(b.image, { sizes: SIZES.half, priority: false, className: 'pb-img' });
            if (!body.trim() && !pic) return '';
            return section(b, `<div class="pb-split pb-split-${b.image_side === 'start' ? 'start' : 'end'}">${pic ? `<figure class="pb-figure pb-split-media">${pic}${b.caption ? `<figcaption>${esc(b.caption)}</figcaption>` : ''}</figure>` : ''}<div class="pb-prose pb-split-text">${body}</div></div>`, { tag: 'div' });
         }
         case 'cardgrid': {
            const cols = [2, 3, 4].includes(b.columns) ? b.columns : 3;
            const cards = (b.items ?? []).filter((x) => str(x.title) && x.title).map((x) => {
               const link = x.url ? href(x.url) : null;
               const pic = image(x.image, { sizes: SIZES.card(cols), priority: false, className: 'pb-img' });
               const title = link ? `<a class="pb-card-link" href="${esc(link)}"${/^https:/i.test(link) ? ' rel="noopener"' : ''}>${esc(x.title)}</a>` : esc(x.title);
               return `<li class="pb-card">${pic ? `<div class="pb-card-media">${pic}</div>` : ''}<div class="pb-card-body"><h3 class="pb-card-t">${title}</h3>${x.text ? `<p class="pb-card-x">${inlineMarkdown(x.text, href)}</p>` : ''}${link && x.label ? `<span class="pb-more" aria-hidden="true">${esc(x.label)}${iconSvg('arrow', 'pb-ic pb-flip')}</span>` : ''}</div></li>`;
            });
            const head = b.heading || b.intro ? `<div class="pb-head">${heading(b.id, b.heading)}${b.intro ? `<p class="pb-intro">${esc(b.intro)}</p>` : ''}</div>` : '';
            return cards.length ? section(b, `${head}<ul class="pb-cards pb-cols-${cols}" role="list">${cards.join('')}</ul>`, { labelled: !!b.heading }) : '';
         }
         case 'cta': {
            const btn = button(b.label, b.url, b.tone === 'quiet' ? 'ghost' : 'primary');
            if (!btn) return '';
            // A button alone (no heading, no text) gets no empty copy column beside it.
            const copy = b.heading || b.text ? `<div class="pb-cta-copy">${heading(b.id, b.heading, 'pb-heading pb-cta-h')}${b.text ? `<p>${esc(b.text)}</p>` : ''}</div>` : '';
            return section(b, `<div class="pb-cta-box${copy ? '' : ' pb-cta-solo'}">${copy}<div class="pb-actions">${btn}</div></div>`, { labelled: !!b.heading });
         }
         case 'quote': {
            if (!str(b.text) || !b.text.trim()) return '';
            const paras = b.text.split(/\n{2,}/).map((p) => `<p>${esc(p).replace(/\n/g, '<br>')}</p>`).join('');
            return b.variant === 'callout'
               ? section(b, `<div class="pb-callout" role="note">${iconSvg('sparkle', 'pb-ic pb-callout-ic')}<div>${paras}${b.cite ? `<p class="pb-cite">${esc(b.cite)}</p>` : ''}</div></div>`, { tag: 'div' })
               : section(b, `<figure class="pb-quote">${iconSvg('quote', 'pb-quote-mark')}<blockquote>${paras}</blockquote>${b.cite ? `<figcaption class="pb-cite">${esc(b.cite)}</figcaption>` : ''}</figure>`, { tag: 'div' });
         }
         case 'faq': {
            const items = (b.items ?? []).filter((x) => str(x.q) && str(x.a) && x.q && x.a);
            if (!items.length) return '';
            const qs = items.map((x) => `<details class="pb-qa"><summary><span>${esc(x.q)}</span>${iconSvg('chevron', 'pb-ic pb-qa-ic')}</summary><div class="pb-qa-a pb-prose">${md(x.a, b.id, 3)}</div></details>`).join('');
            return section(b, `${heading(b.id, b.heading)}<div class="pb-faq-list">${qs}</div>`, { labelled: !!b.heading });
         }
         case 'video': {
            if (b.kind !== 'video' && b.kind !== 'playlist') return '';
            const own = ctx.video?.(b);
            const body = own ?? videoFacade(b);
            return section(b, `<figure class="pb-video">${body}${b.caption ? `<figcaption>${esc(b.caption)}</figcaption>` : ''}</figure>`, { tag: 'div' });
         }
         case 'videos': {
            const items = (b.items ?? []).map((x) => {
               const title = x.title_override || titleOf(x.snapshot, '');
               const link = watch(x.kind, x.ref_id);
               const thumb = x.snapshot?.thumbnail_url;
               const dur = x.kind === 'video' ? fmtDuration(x.snapshot?.duration_seconds) : null;
               const media = `<span class="pb-vthumb${x.kind === 'channel' ? ' pb-vthumb-ch' : ''}">${thumb ? `<img src="${esc(thumb)}" alt="" loading="lazy" decoding="async" width="640" height="360">` : ''}${dur ? `<span class="pb-dur">${esc(dur)}</span>` : ''}${x.kind === 'playlist' ? `<span class="pb-dur">${esc(t.playlist)}</span>` : ''}</span>`;
               const meta = x.snapshot?.channel_name && x.kind !== 'channel' ? `<span class="pb-vmeta">${esc(x.snapshot.channel_name)}</span>` : '';
               const name = `<span class="pb-vtitle">${esc(title)}</span>`;
               return `<li class="pb-vcard">${link ? `<a href="${esc(link)}">${media}${name}</a>` : `${media}${name}`}${meta}</li>`;
            });
            return items.length ? section(b, `${heading(b.id, b.heading)}<ul class="pb-shelf" role="list">${items.join('')}</ul>`, { labelled: !!b.heading }) : '';
         }
         case 'posts': {
            const posts = (b.items ?? []).filter((p) => isObj(p) && str(p.title) && str(p.slug));
            if (!posts.length) return '';
            const items = posts.map((p) => {
               const link = ctx.postHref ? ctx.postHref(p) : href(`/articles/${encodeURIComponent(p.slug)}/`);
               const cover = p.cover ?? p.first_slide?.image ?? null;
               const pic = image(cover, { sizes: '(min-width: 40rem) 12rem, 30vw', priority: false, className: 'pb-img' });
               const date = str(p.published_at) ? fmtDate(p.published_at, L) : null;
               const title = link ? `<a class="pb-card-link" href="${esc(link)}">${esc(p.title)}</a>` : esc(p.title);
               return `<li class="pb-post">${pic ? `<div class="pb-post-media">${pic}</div>` : '<div class="pb-post-media pb-post-ph" aria-hidden="true">' + iconSvg('posts') + '</div>'}<div class="pb-post-body"><h3 class="pb-post-t">${title}</h3>${p.excerpt ? `<p class="pb-post-x">${esc(p.excerpt)}</p>` : ''}${date ? `<p class="pb-post-m"><time datetime="${esc(p.published_at)}">${esc(date)}</time>${p.author_name ? ` · ${esc(p.author_name)}` : ''}</p>` : ''}</div></li>`;
            });
            return section(b, `${heading(b.id, b.heading)}<ul class="pb-posts" role="list">${items.join('')}</ul>`, { labelled: !!b.heading });
         }
         case 'cards':
            // A paged, filterable grid of card posts needs the host's own data reads: hosts render it via `slot`.
            return '';
         case 'stats': {
            const items = (b.items ?? []).filter((x) => str(x.label) && x.label);
            if (!items.length) return '';
            const features = b.variant !== 'stats';
            const lis = items.map((x) =>
               features
                  ? `<li class="pb-feat">${x.icon && FEATURE_ICONS.includes(x.icon) ? `<span class="pb-feat-ic">${iconSvg(x.icon)}</span>` : ''}<div><h3 class="pb-feat-t">${esc(x.label)}</h3>${x.text ? `<p class="pb-feat-x">${inlineMarkdown(x.text, href)}</p>` : ''}</div></li>`
                  : `<li class="pb-stat">${x.value ? `<span class="pb-stat-v">${esc(x.value)}</span>` : ''}<span class="pb-stat-l">${esc(x.label)}</span>${x.text ? `<span class="pb-stat-x">${esc(x.text)}</span>` : ''}</li>`,
            );
            const n = Math.min(4, items.length);
            return section(b, `${heading(b.id, b.heading)}<ul class="${features ? 'pb-feats' : 'pb-stats'} pb-n-${n}" role="list">${lis.join('')}</ul>`, { labelled: !!b.heading });
         }
         case 'divider': {
            const size = ['s', 'm', 'l'].includes(b.size) ? b.size : 'm';
            // style_kind (v2); a CMS that predates the page builder serves only `style` (v1).
            return (b.style_kind ?? b.style) === 'space'
               ? `<div class="pb-b pb-k-divider pb-spacer pb-gap-${size}" data-block="${esc(b.id)}" data-block-type="divider" aria-hidden="true"></div>`
               : section(b, '<hr class="pb-rule">', { cls: `pb-gap-${size}`, tag: 'div' });
         }
         case 'contact': {
            const h = str(b.href) && /^mailto:/i.test(b.href) ? (validEmail(b.href.slice(7)) ? b.href : null) : href(CONTACT_PATH);
            if (!h || !b.label) return '';
            const isMail = h.startsWith('mailto:');
            return section(
               b,
               `<div class="pb-contact-box"><span class="pb-contact-ic">${iconSvg(isMail ? 'mail' : 'chat')}</span><div class="pb-contact-copy">${heading(b.id, b.heading, 'pb-heading pb-contact-h')}${b.text ? `<p>${esc(b.text)}</p>` : ''}${isMail ? `<p class="pb-contact-addr" dir="ltr">${esc(h.slice(7))}</p>` : ''}</div><div class="pb-actions">${`<a class="pb-btn pb-btn-primary" href="${esc(h)}">${esc(b.label)}</a>`}</div></div>`,
               { labelled: !!b.heading },
            );
         }
      }
      return '';
   }
}
